screenshot-annotation-technique.text-find-snippet:
// PRIMARY: Find element by visible text label and annotate it — call via browser_evaluate
// Replace 'YOUR TEXT HERE' with the exact visible label (button text, field label, list item)
// Why TreeWalker instead of querySelector: walks raw text nodes only — no ancestor bleed,
// no script-tag false matches. Also handles split text nodes (e.g. "Count (" + "35" + ")").
(function() {
  const target = 'YOUR TEXT HERE';
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let el = null;
  while (walker.nextNode()) {
    const node = walker.currentNode;
    const text = node.textContent.trim();
    if (text === target) { el = node.parentElement; break; }
    // Split-node fallback: target text spans multiple adjacent text nodes
    if (target.startsWith(text) && text.length > 0) {
      let candidate = node.parentElement;
      while (candidate && !candidate.textContent.includes(target)) candidate = candidate.parentElement;
      if (candidate) { el = candidate; break; }
    }
  }
  if (!el) return false;
  const existing = document.getElementById('__e2e_ann__');
  if (existing) existing.remove();
  const rect = el.getBoundingClientRect();
  if (rect.width === 0 && rect.height === 0) return false;
  const ann = document.createElement('div');
  ann.id = '__e2e_ann__';
  ann.style.cssText = `position:fixed;left:${rect.left-4}px;top:${rect.top-4}px;width:${rect.width+8}px;height:${rect.height+8}px;border:3px solid #FF0000;background:rgba(255,0,0,0.08);border-radius:4px;pointer-events:none;z-index:999999`;
  document.body.appendChild(ann);
  return true;
})();

screenshot-annotation-technique.coordinate-inject-snippet:
// FALLBACK: Use when element has no unique text label, or coordinates are already known
// Replace TOP_PX, LEFT_PX, W_PX, H_PX with values from browser_snapshot
(function() {
  const existing = document.getElementById('__e2e_ann__');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.id = '__e2e_ann__';
  overlay.style.cssText = 'position:fixed;top:TOP_PXpx;left:LEFT_PXpx;width:W_PXpx;height:H_PXpx;border:3px solid #FF0000;background:rgba(255,0,0,0.08);z-index:999999;pointer-events:none;border-radius:4px;';
  document.body.appendChild(overlay);
  return true;
})();

screenshot-annotation-technique.multi-element-snippet:
// Annotate multiple elements by visible text — inject all, take ONE screenshot, remove all
(function() {
  const targets = ['LABEL ONE', 'LABEL TWO'];  // replace with actual visible labels
  ['__e2e_ann_1__', '__e2e_ann_2__'].forEach(id => { const e = document.getElementById(id); if (e) e.remove(); });
  targets.forEach((target, i) => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let el = null;
    while (walker.nextNode()) {
      const node = walker.currentNode;
      const text = node.textContent.trim();
      if (text === target) { el = node.parentElement; break; }
      if (target.startsWith(text) && text.length > 0) {
        let c = node.parentElement;
        while (c && !c.textContent.includes(target)) c = c.parentElement;
        if (c) { el = c; break; }
      }
    }
    if (!el) return;
    const rect = el.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) return;
    const ann = document.createElement('div');
    ann.id = `__e2e_ann_${i+1}__`;
    ann.style.cssText = `position:fixed;left:${rect.left-4}px;top:${rect.top-4}px;width:${rect.width+8}px;height:${rect.height+8}px;border:3px solid #FF0000;background:rgba(255,0,0,0.08);border-radius:4px;pointer-events:none;z-index:999999`;
    document.body.appendChild(ann);
  });
  const injected = targets.filter((_, i) => !!document.getElementById(`__e2e_ann_${i+1}__`)).length;
  return injected; // returns count of overlays actually appended; 0 = all targets missed
})();

pixelmatch-baseline-protocol.comparison-run:
When a baseline exists:
1. Save current screenshot to workspace/[task-id]/snapshots/TC-NNN-current.png
2. Run comparison via Bash:
   node -e "
     const fs = require('fs');
     const { PNG } = require('pngjs');
     const pixelmatch = require('pixelmatch');
     const img1 = PNG.sync.read(fs.readFileSync('baselines/[page-slug].png'));
     const img2 = PNG.sync.read(fs.readFileSync('snapshots/TC-NNN-current.png'));
     const diff = new PNG({ width: img1.width, height: img1.height });
     const changed = pixelmatch(img1.data, img2.data, diff.data, img1.width, img1.height, { threshold: 0.03 });
     fs.writeFileSync('snapshots/TC-NNN-visual-diff.png', PNG.sync.write(diff));
     console.log(changed + ' pixels changed (' + (changed / (img1.width * img1.height) * 100).toFixed(2) + '%)');
     process.exit(changed > img1.width * img1.height * 0.03 ? 1 : 0);
   "
3. If exit code 1 (more than 3% pixels changed):
   - Add to evidence table: TC-NNN | Visual regression: N% pixel change | FAIL | TC-NNN-visual-diff.png
4. If exit code 0: visual baseline matches, log "Visual: baseline match (within 3%)"
